head.script:
scwin.trigger3_onclick = function(e) {
    for (var i = 0; i < grid1.getRowCount(); i++) {
        if (i != 0 && i != 4 && i != 6 && i != 8 && i != 10 && i != 11 && i != 12 && i != 13) {
            grid1.setRowVisible(i, false);
        }
    }
};
scwin.rgb2hex = function(rgb) {
    rgb = rgb.match(/^rgba?[\s+]?\([\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?,[\s+]?(\d+)[\s+]?/i);
    return (rgb && rgb.length === 4) ? "#" +
        ("0" + parseInt(rgb[1], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[2], 10).toString(16)).slice(-2) +
        ("0" + parseInt(rgb[3], 10).toString(16)).slice(-2) : '';
}
scwin._checkRgb = function(id) {
    var rgb = WebSquare.wUnit.getJq(id).css("background-color");
    var color;
    if (rgb.indexOf("rgb") != -1) {
        color = scwin.rgb2hex(rgb);
        return color;
    } else {
        return rgb;
    }
}

scwin.checkVal1 = function() {
    return scwin._checkRgb('#grid1_cell_6_0') == '#000000' || scwin._checkRgb('#grid1_cell_6_0') == 'transparent';
}
scwin.checkVal2 = function() {
    return scwin._checkRgb('#grid1_cell_8_0') == '#fca73c';
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger3').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_6_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_scrollY_div').scrollTop = 50");
    WebSquare.wUnit.addCommand("pause", "500");

    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('grid1_cell_8_0').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal1()", "true");
    WebSquare.wUnit.addCommand("pause", "500");	
    WebSquare.wUnit.addCommand("assert", "scwin.checkVal2()", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.unitTest();
scwin.onpageload = function() {
    window.arr = [];
    for (var i = 0; i < 21; i++) {
        arr.push("row_" + i);
        arr.push("data1");
        arr.push("data2");
    }
    grid1.setData(arr);
}
